import{_ as e,o as l,c as t,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2020-05-04 :: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2020-05-04 :: Ceph Orchestration Meeting","date":"2020-05-04T00:00:00.000Z","updated":"2020-05-08T00:00:00.000Z","tags":["Ceph","Orchestrator","CI/CD","Automation","Testing"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/2020-05-04_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2020/2020-05-04_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780460162000}'),r={name:"posts/2020/2020-05-04_-_-_Ceph_Orchestration_Meeting.md"};function o(s,a,n,h,u,_){return l(),t("div",null,[...a[0]||(a[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h4><ul><li><strong>会议主题</strong>: Orchestrator 周会</li><li><strong>日期</strong>: 2020年5月4日</li><li><strong>参会人员</strong>: [参会人员名单]</li></ul><h4 id="讨论议题" tabindex="-1">讨论议题 <a class="header-anchor" href="#讨论议题" aria-label="Permalink to &quot;讨论议题&quot;">​</a></h4><ol><li><p><strong>Orchestrator CLI 简化</strong>:</p><ul><li>讨论了通过参数和 YAML 文件两种方式创建新服务的问题，决定简化 CLI，避免两者混用。</li><li>计划移除不再使用的特定参数版本。</li></ul></li><li><p><strong>版本发布计划</strong>:</p><ul><li>讨论了即将发布的 Ceph 版本 15.2 的发布时间，预计本周内发布。</li><li>决定在版本发布后合并下一个大的代码提交。</li></ul></li><li><p><strong>测试和集成</strong>:</p><ul><li>讨论了将 Orchestrator 测试集成到 Rook CI/CD 的工作进展。</li><li>提到了使用 Ceph-Demon 模块简化虚拟机设置的方法，计划分享给团队。</li><li>讨论了将 Safe ADM 方法用于更广泛的测试，特别是希望将 Dashboard 集成到 Safe ADM 中。</li></ul></li><li><p><strong>Safe ADM 和 Tautology 集成</strong>:</p><ul><li>讨论了 Safe ADM 与 Tautology 的集成，以及如何提高测试的覆盖率和可靠性。</li><li>提到了一个关于 RGW 的 bug，如果 Safe ADM 中有相应的测试，可能会更早发现。</li></ul></li><li><p><strong>Safe Deploy 的使用</strong>:</p><ul><li>讨论了 Safe Deploy 的使用情况，建议不再关注。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>简化 Orchestrator CLI，移除不再使用的参数。</li><li>在 Ceph 15.2 发布后，合并下一个大的代码提交。</li><li>继续推进 Orchestrator 测试与 Rook CI/CD 的集成工作。</li><li>探索和实施 Safe ADM 在更广泛测试中的应用，特别是 Dashboard 的集成。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>完成 Ceph 15.2 的发布工作。</li><li>合并并发布下一个大的代码提交。</li><li>继续推进 Orchestrator 测试与 Rook CI/CD 的集成。</li><li>探索 Safe ADM 在 Dashboard 和其他组件中的应用。</li><li>寻找资源解决 RGW 相关的 bug，并增加相应的测试。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li>讨论了 Safe ADM 和 Tautology 的集成进展，以及 Safe Deploy 的当前状态。</li><li>确认了 Safe ADM 作为测试工具的潜力和未来发展方向。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><ul><li>会议在确认所有议题讨论完毕后结束，下一次会议时间待定。</li></ul>',13)])])}const p=e(r,[["render",o]]);export{d as __pageData,p as default};
